import imgLogo from '../img/logo.png';
import React, { useState } from 'react';
import { useEffect } from 'react';
import { Config } from "../Config";
import { IsWorking } from '../components/Spinner/Spinner';
import { IsNotWorking } from '../components/Spinner/Spinner';

const configFile = Config();

const apiUrl = configFile.URI_API_LOGIN;
const loginSalvo = false;
const _IMEI = "f46bd2cb8dde1f30";

export async function useloginService(user, pass) {
    try {

        IsWorking();

        const response = await fetch(
            //apiUrl,            
            'token/mobile/login',         
            {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify(
                    {
                        Usuario: user,
                        Senha: pass,
                        IMEI: _IMEI,
                        IdFireBase: "",
                        LoginSalvo: false
                    }
                )
            }
        );

        IsNotWorking();

        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(`HTTP error! Status: ${response.status}, Details: ${errorText}`);
        }

        const data = await response.json();
        return data;

    } catch (error) {
        console.error("Error fetching data:", error);
        throw error;
    }

}
