import React, { createElement, useState } from 'react';
import imgLogo from '../../img/logo.png';
import IconsDescription from '../Icon/Icon';
import '../Sidebar/Sidebar.css';

export default function Sidebar({ userLogin, currentPage, onChangePage, onLogout }) {
    // const [collapsed, setCollapsed] = useState(false);
    // const minimalWidth = "767";
    // var _collapse;

    // if (window.innerWidth <= minimalWidth) {
    //     _collapse = true;
    // }
    // else {
    //     _collapse = false;
    // }

    return (
        <>
            <div
                id='SidebarElement'
                className='sidebar'
            >
                <nav id='SidebarNav'
                >
                    <div
                        className="sidebar-header">
                        <img src={imgLogo} alt="Logo Mantran" />
                        <h2>{userLogin}</h2>
                        {/* <p>ID123</p> */}
                    </div>

                    <ul style={{ listStyle: 'none', padding: 0 }}>
                        {[
                            { key: 'home', label: 'Home', icon: 'home' },
                            { key: 'manifest', label: 'Manifesto', icon: 'description' },
                            { key: 'trips', label: 'Viagens', icon: 'map' },

                        ].map(({ key, label, icon }) => (
                            <li
                                key={key}
                                onClick={() => onChangePage(key)}

                                style={{
                                    padding: '8px 12px',
                                    marginBottom: 8,
                                    backgroundColor: currentPage === key ? '#555' : 'transparent',
                                    cursor: 'pointer',
                                    borderRadius: 4,
                                    alignItems: "center",
                                    display: 'flex'
                                }}
                            >
                                <IconsDescription nameOfIcon={icon} /> {label}
                            </li>
                        ))}

                        <li onClick={onLogout}
                            style={
                                {
                                    padding: '8px 12px',
                                    marginBottom: 8,
                                    cursor: 'pointer',
                                    borderRadius: 4,
                                    alignItems: "center",
                                    display: 'flex'
                                }}>
                            <IconsDescription nameOfIcon={'exit_to_app'} />
                            Sair
                        </li>


                    </ul>
                </nav>


            </div >


        </>
    );

}
