import React, { useState } from 'react';
import jsonData from './config.json';

export function Config() {
    return (
        {
            ENVIRONMENT_TYPE: jsonData.ENVIRONMENT_TYPE,
            URI_API_LOGIN: jsonData.URI_API_LOGIN,
            URI_API_MANIFEST: jsonData.URI_API_MANIFEST,
            
            URI_API_FINISH_INVOICE: jsonData.URI_API_FINISH_INVOICE,
            URI_API_ARRIVE_AT_DESTINY: jsonData.URI_API_ARRIVE_AT_DESTINY
        }
    );
}


export function Config_URI_API_MANIFEST_DESTINY(cD_Filial, nR_Manifesto) {

    return (
        jsonData.URI_API_MANIFEST_DESTINY.replace("{cD_Filial}", cD_Filial).replace("{nR_Manifesto}", nR_Manifesto)
    )
}

export function Config_URI_API_MANIFEST_DESTINY_DOCUMENTS(cD_Filial, nR_Manifesto, cgC_CPF) {
    return (
        jsonData.URI_API_MANIFEST_DESTINY_DOCUMENTS
            .replace("{cD_Filial}", cD_Filial)
            .replace("{nR_Manifesto}", nR_Manifesto)
            .replace("{cgC_CPF}", cgC_CPF)
    )
}


export function Config_URI_API_MANIFEST_DESTINY_DOCUMENTS_INVOICES(tP_Documento, nR_Documento, cgC_CPF, nR_Manifesto) {
    return (
        jsonData.URI_API_MANIFEST_DESTINY_DOCUMENTS_INVOICES
            .replace("{tP_Documento}", tP_Documento)
            .replace("{nR_Documento}", nR_Documento)
            .replace("{cgC_CPF}", cgC_CPF)
            .replace("{nR_Manifesto}", nR_Manifesto)
    )
}

export function Config_URI_API_MANIFEST_OCCURRENCES(cD_Filial, tP_Documento, nR_Documento) {
    return (
        jsonData.URI_API_MANIFEST_OCCURRENCES
            .replace("{cD_Filial}", cD_Filial)
            .replace("{tP_Documento}", tP_Documento)
            .replace("{nR_Documento}", nR_Documento)
    )
}

export function Config_URI_API_MANIFEST_TRIP_WAS_STARTED(cD_Filial, nR_Manifesto) {
    return (
        //{cd_Filial}/{nR_Manifesto}/{usar_Data_Emissao?}
        jsonData.URI_API_MANIFEST_TRIP_WAS_STARTED
            .replace("{cD_Filial}", cD_Filial)
            .replace("{nR_Manifesto}", nR_Manifesto)
    )
}

export function Config_URI_API_MANIFEST_START_TRIP(cD_Filial, nR_Manifesto, usar_Data_Emissao) {
    return (
        jsonData.URI_API_MANIFEST_START_TRIP
            .replace("{cD_Filial}", cD_Filial)
            .replace("{nR_Manifesto}", nR_Manifesto)
            .replace("{usar_Data_Emissao}", usar_Data_Emissao)
    )
}


