import Swal from "sweetalert2";

export function successMessage(textMessage) {
    Swal.fire({
        title: "Sucesso!",
        text: textMessage,
        icon: "success"
    });
}

export function confirmMessage(
    title, text, _function
) {
    Swal.fire({
        title: title,
        text: text,
        showDenyButton: true,
        showCancelButton: true,
        confirmButtonText: `Sim`,
        denyButtonText: `Não`
    });
}

export function errorMessage(error) {
    Swal.fire({
        title: "Erro",
        text: error,
        icon: "error",
    });
}

