import { React, useState } from 'react';
import DeliveryDetails from '../ManifestDocument/ManifestDocumentComponent';
import { getManifestDestinyDocumentsList } from '../../../services/ManifestService';
import { setSelectionRange } from '@testing-library/user-event/dist/utils';



export default function ManifestDestiny({ manifestToDetail, setInvoicePage,
    setCurrentManifestCard, setCurrentDestiny }) {
    const [selectSubCard, setSubCard] = useState(false);
    const [currentSubCard, setCurrentSubCard] = useState(false);

    const fetchDataDocuments = async (_filial, manifesto, cgc_cpf) => {
        try {
            var _cpf_cnpj = cgc_cpf.replaceAll("/", "").replaceAll(".", "").replaceAll("-", "");

            const response = await getManifestDestinyDocumentsList(_filial,
                manifesto, _cpf_cnpj
            );
            const result = response;
            return result;
        }
        catch (error) {
            console.log(error);
        }
    }

    function getDocumentsByDestiny(manifestDestiny, cgC_CPF) {

        if (!selectSubCard) {
            fetchDataDocuments(
                manifestDestiny.cD_Filial,
                manifestDestiny.nR_Manifesto,
                cgC_CPF//catch by item manifest parent
            ).then((response) => {
                var documentsList = response.manifestoDocumentos;
                console.log(documentsList);
                console.log(cgC_CPF);
                console.log(index);

                var index = manifestDestiny.manifestosDestinos.findIndex((x) => x.cgC_CPF === cgC_CPF);

                manifestDestiny.manifestosDestinos[index].manifestosDocumentos = documentsList;

                setSubCard(true);
                setCurrentSubCard(cgC_CPF);

                setCurrentManifestCard('Document');
                setCurrentDestiny(manifestDestiny.manifestosDestinos[index]);

            }).catch((error) => {
                console.log("error -" + error);
            }).finally({

            });
        } else {
            setSubCard(false);
            setCurrentManifestCard('');
            setCurrentDestiny(null);
        }

    }

    return (
        <div
            onClick={
                (e) => {
                    e.stopPropagation();
                }
            }
        >

            <hr></hr>

            <h3
                style={{
                    color: "#8B0000",
                    marginTop: '30px',
                    marginBottom: '10px',
                    textAlign: 'center',
                }}>
                Endereços de Entrega
            </h3>

            <div className='div_manifest'
                style={
                    {
                        //maxHeight : 500 
                        maxHeight: 311,
                        overflowY: 'scroll'
                    }
                }
            >
                {
                    manifestToDetail.manifestosDestinos.map((item) => (

                        <div
                            onClick={(e) => {
                                e.stopPropagation(); // Prevents the event from bubbling up to the parent
                                getDocumentsByDestiny(manifestToDetail, item.cgC_CPF);
                            }}

                            style={
                                {
                                    padding: 10,
                                    fontSize: 13,
                                    backgroundColor: '#ebebeb',
                                    //backgroundColor : 'white',
                                    border: '1px solid #dbdbdb',
                                    borderColor: '#dbdbdb',
                                    borderRadius: 10,
                                    margin: 15,
                                }
                            }>
                            <div style={
                                {
                                    textAlign: 'left',
                                    fontWeight: 'bold',
                                    color: "#8B0000",
                                    paddingtTop: 10,
                                    paddingBottom: 10
                                }
                            }>
                                {item.fantasia_Destino}
                            </div>

                            <p>
                                Cpf/ Cnpj: {item.cgC_CPF}
                            </p>
                            <p>
                                Fantasia: {item.fantasia_Destino}
                            </p>
                            <p>
                                Endereço: {item.endereco}
                            </p>

                            <div style={
                                { textAlign: 'right' }
                            }>

                            </div>
                        </div>

                    ))
                }
            </div>
        </div >
    );
}