import { React, useState } from 'react';
import { ReactRouter } from 'react-dom';

export default function ManifestDocument({ manifest, destiny, setCurrentManifestCard,
    setCurrentDocument

}) {
    const [selectSubCard, setSubCard] = useState(false)

    return (
        <div
            onClick={(e) => {
                e.stopPropagation();
                setSubCard(!selectSubCard)
            }}
        >

            <hr></hr>
            <h3
                style={{
                    color: "#8B0000",
                    marginTop: '30px',
                    marginBottom: '10px',
                    textAlign: 'center',
                }}>
                Detalhes da Entrega | Documentos
            </h3>
            {
                destiny.manifestosDocumentos.map((item) => (

                    <div style={
                        {
                            padding: 10,
                            fontSize: 13,
                            backgroundColor: '#ebebeb',
                            //backgroundColor : 'white',
                            border: '1px solid #dbdbdb',
                            borderColor: 'gray',
                            borderRadius: 10,
                            border: '1px solid gray',
                            backgroundColor: 'white'
                        }


                    }

                        onClick={() => {
                            setCurrentManifestCard('Invoice');
                            setCurrentDocument(item);
                        }}
                    >
                        <div style={
                            {
                                textAlign: 'left',
                                // fontWeight: 'bold',
                                // color: "#8B0000",
                                paddingtTop: 10,
                                paddingBottom: 10
                            }
                        }>
                            Nome Fantasia: {item.fantasia_Destino}
                        </div>

                        <p>
                            Nº Documento: {item.nR_Documento}
                        </p>
                        <p>
                            Tipo Documento: {item.tP_Documento}
                        </p>
                        <p>
                            Endereço: {item.endereco_Completo}
                        </p>
                        <hr></hr>
                    </div>

                ))
            }

        </div >
    );
}