import React, { use, useEffect, useState } from 'react'; import { Tab, Tabs, TabList, TabPanel } from 'react-tabs';
import './Manifest.css';
import Toplevel from '../../components/Toplevel/Toplevel';

import ManifestDestiny from '../Manifest/ManifestDestiny/ManifestDestinyComponent';
import ManifestInvoice from '../Manifest/ManifestInvoice/ManifestInvoiceComponent';
import ManifestDocument from '../Manifest/ManifestDocument/ManifestDocumentComponent';


import { getManifestList } from '../../services/ManifestService';
import { getManifestDestinyList } from '../../services/ManifestService';

//import { ManifestDetailsSectionComponent } from '../ManifestDetailsSection/ManifestDetailsSectionComponent';
import { ManifestDetailsSectionComponent } from '../Manifest/ManifestDetailsSection/ManifestDetailsSectionComponent';

import { ManifestModel } from '../../contexts/models/models/ManifestModel';


const Manifest = ({ setPage, setToken, token }) => {

    const [manifestList, setManifestList] = useState(['']);
    const [currentManifestCard, setCurrentManifestCard] = useState();
    const [currentManifest, setCurrentManifest] = useState();
    const [currentDestiny, setCurrentDestiny] = useState();
    const [currentDocument, setCurrentDocument] = useState();
    const [currentCardToShow, setCurrentCardToShow] = useState();
    const [currentCard, setCurrentCard] = useState(true);
    const [selectCard, setSelectCard] = useState(false);

    //Get manifest list by api first
    useEffect(() => {
        fetchDataManifest()
    },
        []
    );

    //Call manifest list by api
    const fetchDataManifest = async () => {
        try {

            const response = await getManifestList(setToken, token);
            const result = response;

            result.manifestos.forEach(obj => {
                obj.CardIsOpened = false;
            });

            //if sucess was FALSE, call MESSAGE method
            console.log(result.manifestos);
            setManifestList(result.manifestos);
        } catch (error) {
            console.log('error:' + error);
        }
    }

    //Get destiny list by api
    const fetchDataDestiny = async (filial, manifesto) => {
        try {
            const response = await getManifestDestinyList(filial, manifesto);
            const result = response;
            return result;
        } catch (error) {
            console.log(error);
        }
    }

    //Call when manifest card was clicked 
    function getDestinyListByManifest(manifest) {

        if (
            !manifest.CardIsOpened
        ) {
            setSelectCard(false);
            setCurrentManifest(null);
            setCurrentManifestCard('');
            setCurrentDestiny('');
            setCurrentDocument('');
            setCurrentCardToShow(null);
        } else {

            //GET DESTINY LIST
            fetchDataDestiny(manifest.cD_Filial, manifest.nR_Manifesto).then(
                (response) => {

                    var destinyList = response.manifestoDestinos;
                    console.log(destinyList);
                    manifest.manifestosDestinos = destinyList;
                    setCurrentManifest(manifest);
                    setCurrentManifestCard('Destiny');
                    setSelectCard(true);

                }).catch((error) => {
                    console.log("error -" + error);
                }).finally(() => {
                });
        }

        console.log(manifest.nR_Manifesto == currentCard);

        if (manifest.nR_Manifesto != currentCard && currentCard !== true) {
            manifestList.find((x) => x.nR_Manifesto == currentCard).CardIsOpened = false;
        }
    }

    let Content;
    switch (currentManifestCard) {

        case "Destiny":
            Content = <ManifestDestiny
                manifestToDetail={currentManifest}
                setInvoicePage={''}
                setCurrentManifestCard={setCurrentManifestCard}
                setCurrentDestiny={setCurrentDestiny}

            />;
            break;
        case "Document":
            Content = < ManifestDocument
                manifest={currentManifest}
                setCurrentManifestCard={setCurrentManifestCard}
                setCurrentDestiny={setCurrentDestiny}
                setCurrentDocument={setCurrentDocument}
                destiny={currentDestiny}

            />;;
            break;

        case "Invoice":
            Content = <ManifestInvoice
                manifest={currentManifest}
                destiny={currentDestiny}
                setCurrentManifestCard={setCurrentManifestCard}
                document={currentDocument}
                // setPage={setPage}
                // backToFirst={setPage}
                fetchManifestListAgain={fetchDataManifest}
            />;;
            break;
        default:
            Content = ""

            break;
    }

    return (
        <div
            className='window'
        >
            <Toplevel Title={"Meus Manifestos"} />

            <div className="content_manifest"
                style={{
                    marginTop: 60,
                    padding: 20,
                    paddingBottom: 0,
                    display: 'flex',
                    flexWrap: 'wrap',
                    gap: '20px',
                    justifyContent: 'center',
                    display: currentCard ? 'flex' : 'none'
                }}
            >
                {
                    manifestList.map(
                        (manifest) => (
                            <div className="card_manifest"
                                onClick={
                                    () => {
                                        {

                                            setCurrentCard(manifest.nR_Manifesto);
                                            manifest.CardIsOpened = !manifest.CardIsOpened;
                                            var item = new ManifestModel(manifest);
                                            getDestinyListByManifest(item);
                                        }
                                    }
                                }

                                style={{
                                    backgroundColor: 'white',
                                    color: "#000000",
                                    borderRadius: '10px',
                                    padding: '20px',
                                    width: '90%',
                                    maxWidth: '900px',
                                    boxShadow: '0px 2px 5px rgba(0, 0, 0, 0.3)',
                                    textAlign: 'left',
                                    cursor: 'pointer',
                                    transition: 'transform 0.2s ease'
                                }}
                            >
                                <h3
                                    style={{
                                        color: "#8B0000",
                                        marginTop: '0px',
                                        marginBottom: '10px'
                                    }}
                                >Manifesto: nº{manifest.nR_Manifesto}
                                </h3>


                                <p>Previsão: {manifest.dT_Previsao_Entrega}</p>
                                <p>Origem: {manifest.cidade_Origem}</p>
                                <p>Destino: {manifest.cidade_Destino}</p>


                                <div style={{
                                    border: '1 solid gray',
                                    borderRadius: 12
                                }}>

                                    {
                                        currentCard == manifest.nR_Manifesto
                                        &&
                                        manifest.CardIsOpened
                                        &&
                                        Content !== ""
                                        &&
                                        <ManifestDetailsSectionComponent
                                            Content={Content}
                                            currentManifestCard={currentManifestCard}
                                            setCurrentManifestCard={setCurrentManifestCard}
                                            currentManifest={currentManifest}
                                            //setPage={setPage}
                                            fetchManifestListAgain={fetchDataManifest}

                                            
                                        />
                                    }
                                </div>
                            </div>
                        )
                    )
                }
            </div>
        </div >

    )
}

export default Manifest;
