import { React } from 'react-dom';
import { useState, useEffect } from 'react';
import IconsDescription from '../../../components/Icon/Icon';
import { getTripWasStarted } from '../../../services/ManifestService';

import { confirmMessage } from '../../../components/Message/Message';
import { errorMessage } from '../../../components/Message/Message';
import { successMessage } from '../../../components/Message/Message';
import { startTrip } from '../../../services/ManifestService';
import Swal from 'sweetalert2';

export function ManifestDetailsSectionComponent({ Content, setCurrentManifestCard,
    currentManifestCard, currentManifest, fetchManifestListAgain //setPage
}) {

    const [showButton, setShowButton] = useState();
    const [tripWasStarted, setStartedOrNot] = useState(false);
    const [arrivedAtCustomer, setArrivedAtCustomer] = useState(false);

    const fetchData = async () => {

        await getTripWasStarted(currentManifest.cD_Filial, currentManifest.nR_Manifesto).then((response) => {
            console.log(response);
            console.log(response.sucesso);
            console.log(response.chegada);

            setArrivedAtCustomer(response.chegada);
            setShowButton(!response.iniciado);
            setStartedOrNot(response.iniciado);
        })

    }

    useEffect(
        () => {
            console.log('***');
            fetchData();
        }, [showButton]
    )

    async function startTripApi(usar_Data_Emissao) {

        try {
            //cD_Filial, nR_Manifesto, usar_Data_Emissao
            const result = await startTrip(currentManifest.cD_Filial, currentManifest.nR_Manifesto, usar_Data_Emissao);

            if (result.sucesso) {
                successMessage(result.mensagem);
                fetchManifestListAgain();                                
                //setPage('manifest');
            }
            else {
                errorMessage('Erro', result.erros);
            }

        } catch (error) {
            console.log(error);
            errorMessage('Erro', error);

        }
    }

    function startTripAction() {


        var title = 'Inicio de trânsito';
        var text = !arrivedAtCustomer ? 'Deseja iniciar trânsito?' :
            'Já existe data de chegada no cliente neste manifesto!'
            + ' Não é possível iniciar com data atual! Deseja iniciar com a data de emissão do manifesto?';

        Swal.fire(
            {
                title: title,
                text: text,
                showDenyButton: false,
                showCancelButton: true,
                cancelButtonText: 'Cancelar',
                confirmButtonText: `Sim`,
                denyButtonText: `Não`
            }
        )
            .then((result) => {

                if (result.isConfirmed) {
                    var usar_Data_Emissao = arrivedAtCustomer ? true : false;

                    startTripApi(usar_Data_Emissao);


                } else if (result.isDenied) {
                    console.log();
                }

            });

        // }
        // else {
        //     confirmMessage('Início de trânsito', 'Já existe data de chegada no cliente neste manifesto!'
        //         + ' Não é possível iniciar com data atual! Deseja iniciar com a data de emissão do manifesto?')

        // }
    }

    return (


        <div
            style={{
                top: 10
            }}
        >
            {Content}

            <hr />
            <div style={{
                top: 10,
                padding: 10,
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center'
            }}>

                <button
                    style={{
                        borderRadius: 6,
                        backgroundColor: '#ebebeb',
                        height: 41
                    }}
                    onClick={
                        (e) => {
                            e.stopPropagation();
                            setCurrentManifestCard(
                                () => {
                                    switch (currentManifestCard) {
                                        case "Destiny":
                                            return "";
                                            break;
                                        case "Document":
                                            return "Destiny";
                                            break;
                                        case "Invoice":
                                            return "Document";
                                            break;
                                        default:
                                            break;
                                    }
                                }

                            )
                        }
                    }
                >
                    <div>
                        <IconsDescription
                            nameOfIcon={"arrow_back"}
                        />
                    </div>

                </button>

                {

                    showButton && <button

                        className='btn'
                        onClick={(e) => {
                            e.stopPropagation();

                            startTripAction();
                        }}>


                        <div>
                            <IconsDescription
                                nameOfIcon={"traffic"}
                            />
                        </div>

                        <div>
                            Iniciar Trânsito
                        </div>

                    </button>
                }

            </div>
        </div>)
}