import { useEffect, useState } from 'react';
import { React } from 'react-dom';
import {
    getManifestDestinyDocumentsInvoicesList,
    getTransporterWasArrived,
    finishInvoice,
    arriveAtCustomer
} from '../../../services/ManifestService';
import { getOcurrenceList } from '../../../services/OcurrenceService';
import IconsDescription from '../../../components/Icon/Icon';
//import Swal from 'sweetalert2';
import { errorMessage } from '../../../components/Message/Message';
import { successMessage } from '../../../components/Message/Message';
import confirmMessage from '../../../components/Message/Message';

export default function ManifestInvoiceComponent(
    {
        manifest, destiny, document, fetchManifestListAgain //setPage, backToFirst
    }
) {
    //const [objectToFinishInvoices, setobjectToFinishInvoices]
    const [disableArriveButton, setDisableArriveButton] = useState(true);
    const [disableFinishInvoicesButton, setDisableFinishInvoicesButton] = useState(true);

    const [currentOcorrence, setCurrentOcorrence] = useState('');
    const [currentInvoices, setCurrentInvoices] = useState(
        [
            ''
        ]
    );
    const [objectFinishInvoices, setobjectFinishInvoices] = useState(
        {
            CD_Empresa: manifest.cD_Empresa,
            CD_Filial: manifest.cD_Filial,
            CD_Filial_Documento: '',
            NR_Manifesto: manifest.nR_Manifesto,
            TP_documento: document.tP_Documento,
            NR_Documento: document.nR_Documento,
            CGC_CPF_Destinatario: destiny.cgC_CPF,//'',//a ver depois
            CD_Ocorrencia: currentOcorrence,
            Image: [],
            Notas_Fiscais: []
        }
    );

    const [objectArriveAtDestiny, setObjectArriveAtDestiny] = useState(
        {
            CD_Empresa: manifest.cD_Empresa,
            CD_Filial: manifest.cD_Filial,
            NR_Manifesto: manifest.nR_Manifesto,
            TP_documento: document.tP_Documento,
            NR_Documento: document.nR_Documento,
            Notas_Fiscais: []
        }
    );
    const [currentFile, setCurrentFile] = useState();
    const [selectedInvoices, setSelectedInvoices] = useState();
    const [ocorrencias, setOcorrencias] = useState(
        []
    );

    const [showButtonArrive, setShowButtonArrive] = useState(false);

    function handleChangeFile(event) {

        const file = event.target.files[0];

        setCurrentFile(file);
        objectFinishInvoices.Image = file;
    }

    async function finishInvoicesList() {

        if (objectFinishInvoices.Notas_Fiscais.length === 0)
            return errorMessage('Erro - selecione ao menos uma nota fiscal');

        if (objectFinishInvoices.CD_Ocorrencia === '')
            return errorMessage('Erro - selecione ao menos uma ocorrência');


        await finishInvoice(objectFinishInvoices)
            .then(
                (result) => {
                    console.log(result);

                    if (result.sucesso) {
                        successMessage('Sucesso -' + result.mensagem);
                        fetchManifestListAgain();

                    }
                    else {
                        errorMessage(result.mensagem);
                    }
                }
            ).catch(
                (error) => {
                    console.log(error);
                    errorMessage(error);
                }
            ).finally(
                () => {
                    console.log('');
                }
            );


        console.log('finishing at destiny');
    }

    async function getApiTransporterWasArrived() {

        getTransporterWasArrived(
            manifest.cD_Empresa,
            manifest.cD_Filial, document.tP_Documento, document.nR_Documento

        ).then((response) => {

            if (response.sucesso)
                setShowButtonArrive(false); //chegou no cliente
            else
                setShowButtonArrive(true); //não chegou no cliente  

        }
        ).catch((error) => {
            console.log(error);
            errorMessage(error);
        }).finally(() => {
            console.log('');
        });

        console.log('');
    }

    async function arriveAtDestiny() {

        var result = await arriveAtCustomer(objectArriveAtDestiny);

        if (result.sucesso) {
            successMessage(result.mensagem);
            fetchManifestListAgain();
            //setPage('Destiny');    
        }
        else {
            errorMessage(result.erros);
            console.log(result.erros)
        }

        console.log('arriving at destiny');
    }

    const fetchDataOccurence = async () => {
        try {

            getOcurrenceList(manifest.cD_Filial, document.tP_Documento, manifest.nR_Manifesto).then(
                (response) => {
                    if (response.sucesso)
                        setOcorrencias(response.ocorrencias);
                    else
                        console.log(response.erros);

                }
            )
        } catch (error) {
            console.log(error);
        }
    }

    const fetchData = async (document, manifest, _cpf_cnpj) => {
        try {

            const response = await getManifestDestinyDocumentsInvoicesList(
                document.tP_Documento,
                document.nR_Documento, _cpf_cnpj, manifest.nR_Manifesto);

            const result = response;
            return result;

        } catch (error) {
            console.log(error);
        }
    }

    useEffect(() => {


        var _cpf_cnpj = destiny.cgC_CPF.replaceAll("/", "").replaceAll(".", "").replaceAll("-", "");

        fetchData(document, manifest, _cpf_cnpj)
            .then((response) => {

                if (response.sucesso) {

                    response.manifestoNotas.forEach(obj => {
                        obj.Checked = false;
                    });

                    setCurrentInvoices(response.manifestoNotas);

                }
            }

            )
            .catch((error) => {
                console.log("error -" + error);
            })
            .finally(() => {
            });
        fetchDataOccurence();

        getApiTransporterWasArrived();


    }, []);

    const handleChange = (event) => {
        setCurrentOcorrence(event.target.value);
        verifyDisableButtons();

    }

    return (

        <div
            onClick={(e) => {
                e.stopPropagation();
            }}
        >
            <hr />
            <div className="div_manifest">

                <div style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    color: "#8B0000"
                }}>
                    <div
                    ><h4>Notas Fiscais</h4> </div>

                    <div><h4>Doc. nº {document.nR_Documento} | {document.tP_Documento}</h4></div>
                </div>

                {currentInvoices.map((item) =>
                (
                    <div className="info">
                        <input type="checkbox" className="nota-checkbox" value={item.nR_NF}
                            onChange={() => {
                                //console.log('=====');
                                verifyDisableButtons();
                            }
                                //verifyDisableButtons()
                            }

                            onClick={() => {

                                try {
                                    item.Checked = !item.Checked;


                                } catch (error) {
                                    console.log(error);
                                }

                                //send to api invoices checked = true
                                //currentInvoices.findAll               

                                // var listInvoices = currentInvoices.filter(item => item.Checked === true);
                                // console.log(listInvoices);
                            }}

                        />
                        N.F.: {item.nR_NF} | Série:{item.nR_NF_Serie}
                    </div>
                )
                )}

            </div >

            <div className="div_manifest">
                <h4

                    style={{
                        color: "#8B0000",
                        marginTop: '30px',
                        marginBottom: '10px',
                        textAlign: 'left',
                    }}>

                    Ocorrência</h4>
                <select id="ocorrenciaSelect"

                    onClick={(e) => {
                        e.stopPropagation();
                    }}

                    value={currentOcorrence}

                    onChange={
                        (event) => {
                            handleChange(event);
                            console.log(currentOcorrence);
                            //verifyDisableButtons();


                        }


                    }
                    style={{
                        width: '100%',
                        padding: 8,
                        borderRadius: 5,
                        fontSize: 14
                    }}

                >
                    <option
                        onClick={() => {
                            setCurrentOcorrence('')
                        }}
                    ></option>

                    {

                        ocorrencias.map((item) => {
                            return (<option
                                value={item}

                            // onClick={(e) => {
                            //     //     console.log(item);
                            //     //     e.stopPropagation();
                            //     setCurrentOcorrence(item.Value)
                            //     console.log(currentOcorrence);
                            // }}
                            // selected={
                            //     item.Value
                            // () => {
                            //     setCurrentOcorrence(item.Value)
                            // }
                            // }
                            // onChange={
                            //     () => {
                            //         verifyDisableButtons()
                            //     }}
                            >{item}</option>)

                        })
                    }

                </select>
            </div>

            <div className="div_manifest">
                <div className="button-group">

                    {
                        showButtonArrive &&
                        <button className="btn" id="chegadaBtn"

                            disabled={
                                disableArriveButton
                            }
                            onClick={(e) => {
                                e.stopPropagation(e);

                                console.log('arrive at customer');

                                //successMessage('Chegada ao cliente');

                                var listInvoices = currentInvoices.filter(item => item.Checked === true);

                                console.log(listInvoices);

                                objectArriveAtDestiny.Notas_Fiscais = listInvoices;

                                console.log(objectArriveAtDestiny + ' --- ');

                                //errorMessage('Nota(s) não chegaram ao destino(s)');   

                                arriveAtDestiny(); // lembrar de voltar depois
                                //backToFirst('destiny');

                                //setPage('Destiny');
                                //fetchManifestListAgain();

                            }}
                        >
                            <IconsDescription nameOfIcon={"flag"} />
                            Chegada Cliente</button>
                    }

                    <button

                        disabled={
                            disableFinishInvoicesButton
                        }


                        onClick={(e) => {

                            e.stopPropagation(e)

                            console.log('Finish invoice');
                            //errorMessage('Nota(s) não baixada(s)');

                            console.log('finishing invoices');

                            //successMessage('Chegada ao cliente');

                            var listInvoices = currentInvoices.filter(item => item.Checked === true);

                            console.log(listInvoices);

                            objectFinishInvoices.Notas_Fiscais = listInvoices;
                            objectFinishInvoices.CD_Ocorrencia = currentOcorrence;
                            //fetchManifestListAgain();
                            console.log(objectFinishInvoices + ' --- ');

                            finishInvoicesList();//lembrar de voltar depois
                            //errorMessage('Nota(s) não chegaram ao destino(s)');
                            //setPage('destiny');
                            //setPage('back_to_manifest');
                            //setPage('Destiny');

                        }}
                        className="btn" id="baixarBtn" >
                        <IconsDescription nameOfIcon={"cloud_download"} />
                        Baixar Notas</button>

                    <label className="btn">
                        <IconsDescription nameOfIcon={"photo_camera"} />
                        Adicionar Foto
                        <input type="file" id="fotoInput"


                            // onClick={(e) => {
                            //     console.log('upload an photo');
                            //     //Swal.fire("Subindo arquivo");
                            //     //var file = e.
                            //     console.log('');
                            //     console.log(file);

                            //     setPage('Destiny');
                            // }}

                            onChange={(e) => {
                                console.log('');
                                //     const file = e.target.files[0];

                                //     setCurrentFile(file);
                                //     objectFinishInvoices.Image = currentFile;
                                handleChangeFile(e);
                                console.log('');

                            }}
                        />
                    </label>
                </div>

                <span id="chegadaInfo"></span>
                <span id="fotoInfo"></span>
            </div>

        </div >

    );

    function verifyDisableButtons() {

        var listCheckedInvoices = currentInvoices.filter(item => item.Checked === true);
        console.log(listCheckedInvoices);

        if (listCheckedInvoices.length > 0) {

            setDisableArriveButton(false);

            if (currentOcorrence !== undefined || currentOcorrence === '') {
                setDisableFinishInvoicesButton(false);
            }
            else {
                setDisableFinishInvoicesButton(true);
            }
        }
        else {
            setDisableArriveButton(true);
            setDisableFinishInvoicesButton(true);
        }
    }
}