export async function getManifestList(setToken, token) {

    //const token = localStorage.getItem('token');

    try {

        IsWorking();

        const response = await fetch(
            //apiUrlGetManifest, 
            "manifesto/PorCNH",
            {
                method: 'GET',
                headers: {
                    "Content-Type": 'application/json',
                    "Authorization": `Bearer ${token}  `
                    //"Authorization": `Bearer ${undefined}  `
                    //"Authorization": `Bearer 'dadsad45646547`
                }
            }
        );

        IsNotWorking();

        if (!response.ok) {

            IsNotWorking();

            if (response.status == 401) //Not allowed{}
            {
                errorMessage('O usuário não está logado');
                setToken('');

            }

            const errorText = await response.text();
            console.log(errorText);
            throw new Error(`HTTP error! Status: ${response.status}, Details: ${errorText}`);
        }


        const data = await response.json();
        const result = new apiManifestResponseModel(data);

        if (!result.sucesso)
            console.log(result.erros);

        return result;

    } catch (error) {
        console.error("Error fetching data:", error);
        throw error;
    }
}

