import imgLogo from '../img/logo.png';
import React, { useState } from 'react';
import { useEffect } from 'react';
import { Config } from "../Config";
import { Config_URI_API_MANIFEST_DESTINY } from "../Config";
import { Config_URI_API_MANIFEST_DESTINY_DOCUMENTS } from "../Config";
import { Config_URI_API_MANIFEST_DESTINY_DOCUMENTS_INVOICES } from "../Config";
import { Config_URI_API_MANIFEST_OCCURRENCES } from "../Config";
import { IsWorking } from '../components/Spinner/Spinner';
import { IsNotWorking } from '../components/Spinner/Spinner';
import { apiOccurrenceResponseModel } from '../contexts/models/api/occurrence/apiOccurrenceResponseModel';
//import { apiOccurrenceResponse } from '../contexts/models/api/occurrence/apiOccurrenceResponseModel';


export async function getOcurrenceList(cD_Filial, tP_Documento, nR_Manifesto) {

    const apiUrlGetManifest = Config_URI_API_MANIFEST_OCCURRENCES(cD_Filial, tP_Documento, nR_Manifesto);

    const token = localStorage.getItem('token');

    try {

        IsWorking();

        const response = await fetch(
            //apiUrlGetManifest, { 
            `/manifesto/ocorrencia/${cD_Filial}/${tP_Documento}/${nR_Manifesto}`,{
            method: 'GET',
            headers: {
                "Content-Type": 'application/json',
                "Authorization": `Bearer ${token}`
            }
        }
        );

        IsNotWorking();

        if (!response.ok) {

            IsNotWorking();

            const errorText = await response.text();
            throw new Error(`HTTP error! Status: ${response.status}, Details: ${errorText}`);
        }
        const data = await response.json();

        var result = new apiOccurrenceResponseModel(data);

        return result;

    } catch (error) {
        console.error("Error fetching data:", error);
        throw error;
    }
}
