import React, { useState } from 'react';
import Toplevel from '../../components/Toplevel/Toplevel';
import Login from '../Login/LoginComponent';
import IconsDescription from '../../components/Icon/Icon';
import Swal from 'sweetalert2';
import '../../index.css';

export default function Home({ onLogout, toManifest, toTrips }) {

    //const Swal = require('sweetalert2')
    
    return (
        <div>

            <Toplevel Title={"Início"} />

            <div className="content">

                <div className="card"
                    onClick={
                        toManifest
                    }
                >
                    <IconsDescription nameOfIcon={'description'}></IconsDescription>
                    <h3>Manifesto</h3>
                </div>

                <div className="card"
                    onClick={
                        () => alert('Jornada')
                    }
                >

                    <IconsDescription nameOfIcon={'timer'}></IconsDescription>
                    <h3>Jornada</h3>
                </div>
                <div className="card"
                    onClick={
                        toTrips
                    }
                >
                    <IconsDescription nameOfIcon={'map'}></IconsDescription>
                    <h3>Viagens</h3>
                </div>
                <div className="card"
                    onClick={
                        onLogout
                    }
                >
                    <IconsDescription nameOfIcon={'exit_to_app'}></IconsDescription>
                    <h3>Sair</h3>
                </div>

            </div>

        </div>

    );
}
