import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar/Sidebar';
import Home from './pages/Home/HomeComponent';
import Manifest from './pages/Manifest/ManifestComponent';
import Trips from './pages/Trips/TripsComponent';
import Login from './pages/Login/LoginComponent';
import SpinnerLoading from './components/Spinner/Spinner';
import './App.css';

export default function App() {
  const [token, setToken] = useState(localStorage.getItem('token') || null);
  const [userLogin, setUserName] = useState(localStorage.getItem('userlogin') || null);

  const [page, setPage] = useState('home');


  useEffect(() => {
    if (token) {
      localStorage.setItem('token', token);
      localStorage.setItem('userlogin', userLogin)
    } else {
      localStorage.removeItem('token');
      localStorage.removeItem('userlogin');
    }
  }, [token])

  if (!token) {
    return (
      <>
        <SpinnerLoading />
        <Login onLogin={(tok) => setToken(tok)} setUserName={setUserName} />
      </>
    );
  }

  let Content;
  switch (page) {
    case 'home':
      Content = <Home
        onLogout={() => setToken(null)}
        toManifest={() => setPage('manifest')}
        toTrips={() => setPage('trips')}
      />;
      break;
    //case (page == 'manifest' && localStorage.getItem('token') !== null):
    case 'manifest':
      Content = <Manifest setPage={setPage} setToken={setToken} token={token} />;
      break;
    // case 'back_to_manifest':
    //  Content = <Manifest setPage={setPage} setToken={setToken} />
    // break;
    case 'trips':
      Content = <Trips />;
      break;

    default:
      Content = <Home
        onLogout={() => setToken(null)}
        toManifest={() => setPage('manifest')}
        toTrips={() => setPage('trips')}
      />;
  }

  return (
    <div style={{
      display: 'flex',
      height: 'max-content',
      minHeight: '100vh'
    }}>

      {/* <Loading /> */}
      <SpinnerLoading />
      <Sidebar currentPage={page} onChangePage={setPage} onLogout={() => setToken(null)} userLogin={userLogin} />

      <div className='main'
        onClick={() => {

          const sidebar = document.getElementById("SidebarElement");
          const menuButton = document.getElementById('menuButton');

          document.addEventListener('click', function (event) {
            if (!sidebar.contains(event.target) && event.target !== menuButton) {
              sidebar.classList.remove('active');
            }
          });
        }
        } style={{}}
      >{Content}</div>
    </div >
  );
}
