import React, { useState, useEffect } from 'react';
import './Login.css';
import { useloginService } from '../../services/LoginService';
import IconsDescription from '../../components/Icon/Icon';
import imgLogo from '../../img/logo.png'
// import { loginApiResponse } from '../../contexts/models/api/login/apiLoginResponseModel';

export default function Login({ onLogin, setUserName }) {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState(null);

    // Simula chamada API que retorna token
    const handleSubmit = async (e) => {
        e.preventDefault();
        setError(null);
        var data = {};
        try {
            //data.token = await fakeApiLogin(username, password);

            try {
                try {
                    data = await useloginService(username, password);

                    if (data.erros.length > 0) {
                        var erros = data.erros[0].descricao;
                        setError(erros);
                    }

                    if (data.token == null)
                        data.token = "";

                } catch (err) {
                    setError(err);
                } finally {
                }

            } catch (err) {
                setError(err.message);
            }
            setUserName(username);
            onLogin(data.token);
        } catch (err) {
            setError(err.message);
        }
    };

    return (

        <div
            className="login-box"
            style={{
                height: '100vh',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                // backgroundColor: '#eee',
                background: 'linear-gradient(to right, #8B0000, #000000)'
            }}
        >

            <form
                onSubmit={handleSubmit}

                style={{
                    backgroundColor: 'white',
                    padding: 30,
                    borderRadius: 8,
                    boxShadow: '0 0 10px rgba(0,0,0,0.1)',
                    width: 300,
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 12,
                }}
            >

                <img src={imgLogo} alt="Logo Mantran" style={{ margin: '0px auto' }} />

                <h2>
                    Bem-vindo ao Mantran Mobile
                </h2>

                {error && <p style={{ color: 'red' }}>{error}</p>}
                {!error && <p>Entre para continuar</p>}

                <div className="input-group">
                    <IconsDescription nameOfIcon={'person'}></IconsDescription>

                    <input
                        autoComplete='off'
                        placeholder="Informe seu usuário"
                        value={username}
                        onChange={(e) => setUsername(e.target.value)}
                        required
                        autoFocus
                        name="password"

                        style={{
                            paddingTop: 8, paddingBottom: 8,
                            fontSize: 16, width: 180

                        }}
                    />
                </div>

                <div className="input-group">
                    <IconsDescription nameOfIcon={'lock'}></IconsDescription>
                    <input
                        name='password'
                        autoComplete='off'
                        type="password"
                        placeholder="Informe sua senha"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        required
                        style={{
                            paddingTop: 8, paddingBottom: 8,
                            fontSize: 16, width: 180
                        }}
                    />
                </div>


                <button
                    type="submit"
                    className="btn-login"
                    style={{
                    }}
                >
                    Entrar
                </button>
            </form>

            <div className="footer">
                www.mantran.com.br
            </div>

        </div>
    );
}
